### 2. HTTP Request Inspector Module

This module inspects HTTP headers, the query string, and the raw body payload. It reads request streams safely by buffering them so downstream pipeline components (like controllers) can still process the request.

```csharp
using Microsoft.AspNetCore.Http;
using System.Text;
using System.Text.RegularExpressions;

namespace ModularWaf.Core.Inspectors
{
    public class SqlInjectionInspector : IRequestInspector
    {
        // Compilation-optimized regular expressions targeting common SQL Injection vectors
        private static readonly Regex[] SqlInjectionPatterns = new[]
        {
            new Regex(@"\b(union\s+(all\s+)?select)\b", RegexOptions.IgnoreCase | RegexOptions.Compiled),
            new Regex(@"\b(select|insert|update|delete|drop|alter|truncate)\b.*\b(from|into|set|where|table)\b", RegexOptions.IgnoreCase | RegexOptions.Compiled),
            new Regex(@"\b(exec\s*\(|xp_cmdshell|sp_executesql)\b", RegexOptions.IgnoreCase | RegexOptions.Compiled),
            new Regex(@"('|--|#|\/\*|\*\/)", RegexOptions.Compiled), // SQL comment and string delimiter triggers
            new Regex(@"\bwaitfor\s+delay\s+'\d{2}:\d{2}:\d{2}'", RegexOptions.IgnoreCase | RegexOptions.Compiled), // Blind SQLi time-based
            new Regex(@"\bOR\s+['""]?\d+['""]?\s*=\s*['""]?\d+['""]?", RegexOptions.IgnoreCase | RegexOptions.Compiled) // Tautology threats: OR '1'='1'
        };

        private static readonly string[] MonitoredHeaders = { "User-Agent", "Referer", "Cookie", "X-Forwarded-For" };

        public async Task<(bool IsMalicious, string MatchedRule, string ViolationSnippet)> InspectAsync(HttpContext context)
        {
            // 1. Inspect Query Parameters
            foreach (var queryParam in context.Request.Query)
            {
                foreach (var value in queryParam.Value)
                {
                    if (string.IsNullOrEmpty(value)) continue;
                    var (isMatch, pattern) = MatchPatterns(value);
                    if (isMatch)
                    {
                        return (true, $"SQLi in Query Parameter: '{queryParam.Key}'", SanitizeSnippet(value, pattern));
                    }
                }
            }

            // 2. Inspect Target Headers
            foreach (var headerName in MonitoredHeaders)
            {
                if (context.Request.Headers.TryGetValue(headerName, out var headerValue))
                {
                    var combinedHeader = string.Join(" ", headerValue.ToArray());
                    var (isMatch, pattern) = MatchPatterns(combinedHeader);
                    if (isMatch)
                    {
                        return (true, $"SQLi in Header: '{headerName}'", SanitizeSnippet(combinedHeader, pattern));
                    }
                }
            }

            // 3. Inspect Body Payload
            if (context.Request.ContentLength > 0 && 
                (context.Request.ContentType?.Contains("application/json") == true || 
                 context.Request.ContentType?.Contains("application/x-www-form-urlencoded") == true))
            {
                context.Request.EnableBuffering(); // Allows the stream to be read multiple times

                using (var reader = new StreamReader(
                    context.Request.Body, 
                    encoding: Encoding.UTF8, 
                    detectEncodingFromByteOrderMarks: true, 
                    bufferSize: 2048, 
                    leaveOpen: true))
                {
                    var body = await reader.ReadToEndAsync();
                    context.Request.Body.Position = 0; // Reset stream pointer for downstream routing

                    var (isMatch, pattern) = MatchPatterns(body);
                    if (isMatch)
                    {
                        return (true, "SQLi in Body Payload", SanitizeSnippet(body, pattern));
                    }
                }
            }

            return (false, string.Empty, string.Empty);
        }

        private (bool IsMatch, string Pattern) MatchPatterns(string input)
        {
            var decodedInput = Uri.UnescapeDataString(input);
            foreach (var regex in SqlInjectionPatterns)
            {
                if (regex.IsMatch(decodedInput))
                {
                    return (true, regex.ToString());
                }
            }
            return (false, string.Empty);
        }

        private string SanitizeSnippet(string input, string pattern)
        {
            // Clean control characters and cap string length to avoid log-injection/forgery attacks
            var clean = Regex.Replace(input, @"[\r\n\t]", " ").Trim();
            if (clean.Length > 100) clean = clean[..100] + "...[TRUNCATED]";
            return $"Pattern: [{pattern}] Context: [{clean}]";
        }
    }
}
```

