### 3. Rate Limiting and IP Reputation Engine

This module executes sliding window tracking to prevent DoS/Brute Force attacks and manages dynamic reputation scoring. It uses thread-safe structures to protect state transitions.

```csharp
using System.Collections.Concurrent;
using System.Net;

namespace ModularWaf.Core.Reputation
{
    public class IPReputationEngine : IIPReputationEngine
    {
        private readonly int _maxRequestsPerWindow;
        private readonly TimeSpan _slidingWindowSize;
        private readonly int _blockScoreThreshold;
        private readonly TimeSpan _blockDuration;

        // Concurrent storage architectures
        private readonly ConcurrentDictionary<IPAddress, ConcurrentQueue<DateTime>> _requestTracker = new();
        private readonly ConcurrentDictionary<IPAddress, int> _violationScores = new();
        private readonly ConcurrentDictionary<IPAddress, DateTime> _blockedIPs = new();
        private readonly ConcurrentHashSet<IPAddress> _whitelist = new();

        public IPReputationEngine(int maxRequests = 100, int windowSeconds = 60, int blockThreshold = 100, int blockDurationMinutes = 15)
        {
            _maxRequestsPerWindow = maxRequests;
            _slidingWindowSize = TimeSpan.FromSeconds(windowSeconds);
            _blockScoreThreshold = blockThreshold;
            _blockDuration = TimeSpan.FromMinutes(blockDurationMinutes);
        }

        public bool IsIPBlocked(IPAddress clientIp)
        {
            if (_whitelist.Contains(clientIp)) return false;

            if (_blockedIPs.TryGetValue(clientIp, out var expiryTime))
            {
                if (DateTime.UtcNow < expiryTime)
                {
                    return true;
                }
                _blockedIPs.TryRemove(clientIp, out _); // Expire block dynamically
            }

            return false;
        }

        public bool TrackRequestAndCheckRateLimit(IPAddress clientIp)
        {
            if (_whitelist.Contains(clientIp)) return true;

            var now = DateTime.UtcNow;
            var windowStart = now - _slidingWindowSize;

            var requestQueue = _requestTracker.GetOrAdd(clientIp, _ => new ConcurrentQueue<DateTime>());

            // Enqueue current request
            requestQueue.Enqueue(now);

            // Evict outdated timestamps outside current sliding window
            while (requestQueue.TryPeek(out var timestamp) && timestamp < windowStart)
            {
                requestQueue.TryDequeue(out _);
            }

            if (requestQueue.Count > _maxRequestsPerWindow)
            {
                IncrementViolationScore(clientIp, 20); // Impose instant reputation penalty
                return false; 
            }

            return true;
        }

        public void IncrementViolationScore(IPAddress clientIp, int severityScore)
        {
            if (_whitelist.Contains(clientIp)) return;

            var updatedScore = _violationScores.AddOrUpdate(clientIp, severityScore, (_, current) => current + severityScore);

            if (updatedScore >= _blockScoreThreshold)
            {
                _blockedIPs[clientIp] = DateTime.UtcNow.Add(_blockDuration);
            }
        }

        public int GetViolationScore(IPAddress clientIp)
        {
            return _violationScores.TryGetValue(clientIp, out var score) ? score : 0;
        }

        public void WhitelistIP(IPAddress clientIp)
        {
            _whitelist.Add(clientIp);
            _blockedIPs.TryRemove(clientIp, out _);
            _violationScores.TryRemove(clientIp, out _);
        }
    }

    // Helper Thread-Safe Class for Whitelists
    internal class ConcurrentHashSet<T> where T : notnull
    {
        private readonly ConcurrentDictionary<T, byte> _dictionary = new();
        public bool Add(T item) => _dictionary.TryAdd(item, 0);
        public bool Contains(T item) => _dictionary.ContainsKey(item);
        public bool Remove(T item) => _dictionary.TryRemove(item, out _);
    }
}
```

