### 5. WAF Middleware Orchestrator

The main middleware integrates the inspector, rate limiter, reputation manager, and dynamic logging system directly into the request processing loop.

```csharp
using Microsoft.AspNetCore.Http;
using System.Net;
using ModularWaf.Core.Inspectors;
using ModularWaf.Core.Reputation;
using ModularWaf.Core.Response;

namespace ModularWaf.Core.Middleware
{
    public class WebApplicationFirewallMiddleware
    {
        private readonly RequestDelegate _next;
        private readonly IRequestInspector _inspector;
        private readonly IIPReputationEngine _reputationEngine;
        private readonly IIncidentResponder _responder;

        public WebApplicationFirewallMiddleware(
            RequestDelegate next,
            IRequestInspector inspector,
            IIPReputationEngine reputationEngine,
            IIncidentResponder responder)
        {
            _next = next;
            _inspector = inspector;
            _reputationEngine = reputationEngine;
            _responder = responder;
        }

        public async Task InvokeAsync(HttpContext context)
        {
            var clientIp = context.Connection.RemoteIpAddress;

            if (clientIp == null)
            {
                // Fallback / fail closed if identity cannot be validated
                context.Response.StatusCode = StatusCodes.Status400BadRequest;
                await context.Response.WriteAsync("WAF Block: Client Address Resolution Failed.");
                return;
            }

            // Phase 1: Verify Host Ban State
            if (_reputationEngine.IsIPBlocked(clientIp))
            {
                context.Response.StatusCode = StatusCodes.Status403Forbidden;
                await context.Response.WriteAsync("WAF Block: Network Access Suspended.");
                return;
            }

            // Phase 2: Check Rate Limit (Sliding Window Check)
            if (!_reputationEngine.TrackRequestAndCheckRateLimit(clientIp))
            {
                await _responder.HandleViolationAsync(
                    clientIp, 
                    "Rate Limit Overflow", 
                    $"Exceeded safe requests limit threshold.", 
                    severityScore: 15
                );

                context.Response.StatusCode = StatusCodes.Status429TooManyRequests;
                await context.Response.WriteAsync("WAF Block: Request Limit Exceeded.");
                return;
            }

            // Phase 3: Perform Structural Signature Analysis
            try
            {
                var (isMalicious, ruleMatched, snippet) = await _inspector.InspectAsync(context);
                if (isMalicious)
                {
                    // Match severity based on rule triggers; SQLi is critical
                    await _responder.HandleViolationAsync(
                        clientIp, 
                        "SQL-Injection Signature Detected", 
                        $"Triggered rule: {ruleMatched} | Snippet: {snippet}", 
                        severityScore: 40 // Generates quick progression toward blocking thresholds
                    );

                    context.Response.StatusCode = StatusCodes.Status403Forbidden;
                    await context.Response.WriteAsync("WAF Block: Suspicious Activity Detected.");
                    return;
                }
            }
            catch (Exception)
            {
                // Fail Closed Architecture Strategy - deny execution on parsing exceptions
                context.Response.StatusCode = StatusCodes.Status500InternalServerError;
                await context.Response.WriteAsync("WAF Error: Security execution fault encountered.");
                return;
            }

            // All checks passed successfully
            await _next(context);
        }
    }
}
