### Setup and Integration Guide

#### Step 1: Add Extension Methods
Add an extension class to neatly configure and bootstrap dependency injections in your `Program.cs`.

```csharp
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using ModularWaf.Core;
using ModularWaf.Core.Inspectors;
using ModularWaf.Core.Middleware;
using ModularWaf.Core.Reputation;
using ModularWaf.Core.Response;

namespace ModularWaf
{
    public static class WafServiceExtensions
    {
        public static IServiceCollection AddModularWaf(this IServiceCollection services)
        {
            // Register as Singleton to retain the reputation score state across incoming connections
            services.AddSingleton<IIPReputationEngine>(_ => new IPReputationEngine(
                maxRequests: 60,       // Max requests in window
                windowSeconds: 60,     // Window size (1 minute)
                blockThreshold: 100,   // Aggressive block limit
                blockDurationMinutes: 15
            ));

            services.AddSingleton<IRequestInspector, SqlInjectionInspector>();
            services.AddSingleton<IIncidentResponder, IncidentResponseSubsystem>();

            return services;
        }

        public static IApplicationBuilder UseModularWaf(this IApplicationBuilder app)
        {
            return app.UseMiddleware<WebApplicationFirewallMiddleware>();
        }
    }
}
```

#### Step 2: Configure `Program.cs`
Register the services and add the WAF to your HTTP pipeline:

```csharp
var builder = WebApplication.CreateBuilder(args);

// Register Modular WAF dependencies
builder.Services.AddModularWaf();

var app = builder.Build();

// Enable WAF Middleware first in the pipeline to protect downstream dependencies
app.UseModularWaf();

app.MapGet("/", () => "Protected Application Node Running");
app.MapPost("/submit", () => "Data Handled Cleanly");

app.Run();
```

